import type { OperationalWorkflow } from '../types';

interface CompactWorkflowSeed {
  id: string;
  name: string;
  domain: string;
  objective: string;
  trigger: string;
  roles: string[];
  inputs: string[];
  validations: string[];
  steps: Array<[string, string, string, string]>;
  normalPath: string;
  exceptionPath: string;
  recoveryPath: string;
  modules: string[];
  approvals: string[];
  automations: string[];
  aiPoints: string[];
  humanGates: string[];
  outputs: string[];
  audits: string[];
  kpis: string[];
  security: string[];
}

function buildWorkflow(seed: CompactWorkflowSeed): OperationalWorkflow {
  return {
    workflowId: seed.id,
    workflowName: seed.name,
    domain: seed.domain,
    businessObjective: seed.objective,
    triggerEvent: seed.trigger,
    participatingRoles: seed.roles,
    inputData: seed.inputs,
    validationRules: seed.validations,
    stepByStepProcess: seed.steps.map(([actor, action, systemModule, stateTransition], idx) => ({
      stepNumber: idx + 1,
      actor,
      action,
      systemModule,
      stateTransition,
    })),
    normalPath: seed.normalPath,
    exceptionPath: seed.exceptionPath,
    recoveryPath: seed.recoveryPath,
    systemModulesInvolved: seed.modules,
    approvalsAndExceptions: seed.approvals,
    automationsAndNotifications: seed.automations,
    aiAssistancePoints: seed.aiPoints,
    humanReviewGates: seed.humanGates,
    outputRecordsCreated: seed.outputs,
    auditEventsLogged: seed.audits,
    kpisMeasured: seed.kpis,
    securityAccessControls: seed.security,
  };
}

